17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.samples.petclinic.util.Households;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
110	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
111	        }
112	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
113	        rejectDuplicateTelephone(telephone);
114	        owner.setTelephone(telephone);
115	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
116	        if (owner.getRegistrationDate() == null) {
117	            owner.setRegistrationDate(java.time.LocalDate.now());
118	        }
119	        owner.setCustomerCode(assignCustomerCode(owner.getLastName()));
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    /**
128	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'} where
129	     * LAST3 is the upper-cased first three letters of the last name and NNNN is a global 4-digit
130	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
131	     *
132	     * @param lastName the owner's last name
133	     * @return the assigned customer code
134	     */
135	    private String assignCustomerCode(String lastName) {
136	        String name = lastName == null ? "" : lastName;
137	        String last3 = name.substring(0, Math.min(3, name.length()))
138	            .toUpperCase(java.util.Locale.ROOT);
139	        int sequence = this.clinicService.findAllOwners().size() + 1;
140	        return String.format("%s-%04d", last3, sequence);
141	    }
142	
143	    /**
144	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
145	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
146	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
147	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
148	     * {@code "+61412345678"}. The E.164 value is stored and returned.
149	     *
150	     * @param telephone the raw telephone as submitted
151	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
152	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
153	     */
154	    private String normalizeTelephone(String telephone) {
155	        String raw = telephone == null ? "" : telephone.trim();
156	        boolean hasCountryCode = raw.startsWith("+");
157	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
158	        if (hasCountryCode) {
159	            cleaned = cleaned.substring(1);
160	        }
161	        String digits;
162	        if (hasCountryCode) {
163	            digits = cleaned;
164	        } else {
165	            if (cleaned.startsWith("0")) {
166	                cleaned = cleaned.substring(1);
167	            }
168	            digits = "61" + cleaned;
169	        }
170	        if (!digits.matches("[0-9]{8,15}")) {
171	            throw new InvalidTelephoneException(telephone);
172	        }
173	        return "+" + digits;
174	    }
175	
176	    /**
177	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
178	     * multi-character top-level label. Deliberately lenient about the exact character set while still
179	     * rejecting values that are clearly not addresses (e.g. missing '@').
180	     */
181	    private static final java.util.regex.Pattern EMAIL_PATTERN =
182	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
183	
184	    /**
185	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
186	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
187	     * lower-cased before being stored and returned.
188	     *
189	     * @param email the raw email as submitted, may be {@code null}
190	     * @return the lower-cased email, or {@code null} when none was supplied
191	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
192	     */
193	    private String normalizeEmail(String email) {
194	        if (email == null || email.isBlank()) {
195	            return null;
196	        }
197	        String trimmed = email.trim();
198	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
199	            throw new InvalidEmailException(email);
200	        }
201	        return trimmed.toLowerCase(java.util.Locale.ROOT);
202	    }
203	
204	    /**
205	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
206	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
207	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
208	     * {@code "+61 412 345 678"}) are still treated as duplicates.
209	     *
210	     * @param telephone the E.164 telephone of the owner being created
211	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
212	     */
213	    private void rejectDuplicateTelephone(String telephone) {
214	        boolean duplicate = this.clinicService.findAllOwners().stream()
215	            .map(Owner::getTelephone)
216	            .filter(existing -> existing != null)
217	            .map(this::toE164OrNull)
218	            .filter(existing -> existing != null)
219	            .anyMatch(telephone::equals);
220	        if (duplicate) {
221	            throw new DuplicateTelephoneException(telephone);
222	        }
223	    }
224	
225	    /**
226	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
227	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
228	     */
229	    private String toE164OrNull(String telephone) {
230	        try {
231	            return normalizeTelephone(telephone);
232	        } catch (InvalidTelephoneException e) {
233	            return null;
234	        }
235	    }
236	
237	    /**
238	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
239	     * already has the same last name and the same address. Both fields are compared
240	     * case-insensitively and with runs of whitespace collapsed to a single space (and surrounding
241	     * whitespace trimmed), so values that differ only in letter case or spacing still count as a
242	     * match. This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
243	     *
244	     * @param lastName the last name of the owner being created
245	     * @param address the address of the owner being created
246	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
247	     */
248	    private void rejectDuplicateHousehold(String lastName, String address) {
249	        String normalizedLastName = Households.normalize(lastName);
250	        String normalizedAddress = Households.normalize(address);
251	        boolean duplicate = this.clinicService.findAllOwners().stream()
252	            .anyMatch(existing ->
253	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
254	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
255	        if (duplicate) {
256	            throw new DuplicateHouseholdException(lastName, address);
257	        }
258	    }
259	
260	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
261	    @Override
262	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
263	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
264	        if (currentOwner == null) {
265	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	        }
267	        currentOwner.setAddress(ownerFieldsDto.getAddress());
268	        currentOwner.setCity(ownerFieldsDto.getCity());
269	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
270	        currentOwner.setLastName(ownerFieldsDto.getLastName());
271	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
272	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
273	        this.clinicService.saveOwner(currentOwner);
274	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
275	    }
276	
277	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
278	    @Transactional
279	    @Override
280	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
281	        Owner owner = this.clinicService.findOwnerById(ownerId);
282	        if (owner == null) {
283	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	        }
285	        this.clinicService.deleteOwner(owner);
286	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
287	    }
288	
289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
292	        Owner owner = this.clinicService.findOwnerById(ownerId);
293	        if (owner == null) {
294	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
295	        }
296	        HttpHeaders headers = new HttpHeaders();
297	        Pet pet = petMapper.toPet(petFieldsDto);
298	        owner.setId(ownerId);
299	        pet.setOwner(owner);
300	        pet.getType().setName(null);
301	        this.clinicService.savePet(pet);
302	        PetDto petDto = petMapper.toPetDto(pet);
303	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
304	            .buildAndExpand(pet.getId()).toUri());
305	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
306	    }
307	
308	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
309	    @Override
310	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
311	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
312	        if (currentOwner != null) {
313	            Pet currentPet = this.clinicService.findPetById(petId);
314	            if (currentPet != null) {
315	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
316	                currentPet.setName(petFieldsDto.getName());
317	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
318	                this.clinicService.savePet(currentPet);
319	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
320	            }
321	        }
322	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
328	        HttpHeaders headers = new HttpHeaders();
329	        Visit visit = visitMapper.toVisit(visitFieldsDto);
330	        Pet pet = new Pet();
331	        pet.setId(petId);
332	        visit.setPet(pet);
333	        this.clinicService.saveVisit(visit);
334	        VisitDto visitDto = visitMapper.toVisitDto(visit);
335	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
336	            .buildAndExpand(visit.getId()).toUri());
337	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
338	    }
339	
340	
341	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
342	    @Override
343	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
344	        Owner owner = this.clinicService.findOwnerById(ownerId);
345	        if (owner != null) {
346	            Pet pet = owner.getPet(petId);
347	            if (pet != null) {
348	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
349	            }
350	        }
351	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	    }
353	}
